import glob
import os

# Get all polymorph JSON files
polymorph_dir = 'polymorph_data'
polymorph_files = glob.glob(os.path.join(polymorph_dir, '*_polymorphs.json'))

filtered_data = []

for file_path in polymorph_files:
    composition = os.path.basename(file_path).replace('_polymorphs.json', '')
    try:
        with open(file_path, 'r') as f:
            polymorphs = json.load(f)
            for item in polymorphs:
                item['source_composition'] = composition
                filtered_data.append(item)
    except Exception as e:
        print(f'Error reading {file_path}: {e}')

print(f'Consolidated {len(filtered_data)} polymorphs from {len(polymorph_files)} files')"}, 'result': '{
